//! The AL language catalog (`docs/language-catalog.json`): every data type, method overload,
//! trigger, trigger event, property (with its values), statement keyword and attribute the AL
//! language server offers, per BC major. Generated by `tools/language-catalog/generate.sh`, which
//! asks the language server of each major's AL Language extension about probe files the way VS
//! Code does (completion and signature help; names and signatures only, nothing of Microsoft's is
//! committed). The coverage maps use it as their catalog, so a gap shows even where neither the
//! runtime nor Microsoft's apps mention an item.

use std::path::Path;

/// The catalog file, relative to the repository root.
pub const PATH: &str = "docs/language-catalog.json";

/// One item of the catalog.
#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
pub struct Entry {
    pub area: String,
    #[serde(default)]
    pub owner: String,
    pub name: String,
    /// Parameter types, `(Text, var Integer, [Boolean], Joker...)`: `[..]` optional, `...` repeats.
    #[serde(default)]
    pub sig: String,
    #[serde(default)]
    pub params: String,
    #[serde(default)]
    pub returns: String,
    #[serde(default, rename = "static")]
    pub is_static: bool,
    #[serde(default)]
    pub property: bool,
    #[serde(default, rename = "type")]
    pub value_type: String,
    #[serde(default)]
    pub values: Vec<String>,
    #[serde(default)]
    pub in_extensions: bool,
    /// `OnPrem` when not available in the cloud.
    #[serde(default)]
    pub scope: String,
    #[serde(default)]
    pub since_runtime: String,
    #[serde(default)]
    pub deprecated_runtime: String,
    /// The server marked it deprecated.
    #[serde(default)]
    pub deprecated: bool,
    /// The BC majors whose language server offers the item.
    pub bc: Vec<u32>,
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
pub struct Source {
    pub bc: u32,
    pub al_extension: String,
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Deserialize)]
pub struct LanguageCatalog {
    pub sources: Vec<Source>,
    pub items: Vec<Entry>,
}

impl LanguageCatalog {
    pub fn parse(json: &str) -> Result<LanguageCatalog, String> {
        serde_json::from_str(json).map_err(|e| format!("{PATH}: {e}"))
    }

    pub fn load(root: &Path) -> Result<LanguageCatalog, String> {
        let text = std::fs::read_to_string(root.join(PATH)).map_err(|e| format!("{PATH}: {e}"))?;
        LanguageCatalog::parse(&text)
    }

    pub fn area<'a>(&'a self, area: &'a str) -> impl Iterator<Item = &'a Entry> + 'a {
        self.items.iter().filter(move |e| e.area == area)
    }

    /// `27-29`, or the list when not contiguous.
    pub fn majors(&self) -> String {
        majors(&self.sources.iter().map(|s| s.bc).collect::<Vec<_>>())
    }
}

/// `27-29` for a contiguous run, `27, 29` otherwise.
pub fn majors(bc: &[u32]) -> String {
    match (bc.first(), bc.last()) {
        (Some(a), Some(b)) if bc.len() > 1 && (b - a) as usize + 1 == bc.len() => format!("{a}-{b}"),
        _ => bc.iter().map(u32::to_string).collect::<Vec<_>>().join(", "),
    }
}

/// How far the runtime gets with an item.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum State {
    /// The runtime handles it: a registered builtin implementation, or (behavior) its source reads the name.
    Implemented,
    /// The runtime knows it and refuses it explicitly (an unimplemented catalog overload, or an
    /// object kind whose unknown properties or triggers the lowering refuses).
    Refused,
    /// The runtime does not know it (a method missing from the runtime catalog, a name its source never reads).
    Unknown,
}

impl State {
    pub fn label(self) -> &'static str {
        match self {
            State::Implemented => "implemented",
            State::Refused => "refused",
            State::Unknown => "unknown",
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Methods: compiler overloads against the runtime's builtin catalog (ADR-008 signatures)

/// The receiver name the runtime catalog uses for a compiler type (the compiler calls the record
/// type `Table` and splits the instance methods of codeunits, queries, reports and xmlports off
/// into `<Kind>Instance`).
pub fn runtime_receiver(owner: &str) -> &str {
    match owner {
        "Table" => "Record",
        "CodeunitInstance" => "Codeunit",
        "QueryInstance" => "Query",
        "ReportInstance" => "Report",
        "XmlportInstance" => "Xmlport",
        "EnumType" => "Enum",
        // The checker types a TextConst as a Label (al-sema/src/types.rs: `"label" | "textconst" => Ty::Label`),
        // so its calls resolve to the Label overloads.
        "TextConst" => "Label",
        o => o,
    }
}

/// The shape of one parameter, for matching.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Shape {
    /// Lower case, normalized (`joker` is `any`, `array[] of x` is `array of [x]`, `string` is `text`, `table` is `record`).
    pub ty: String,
    pub by_var: bool,
    pub optional: bool,
    pub variadic: bool,
}

fn norm_type(t: &str) -> String {
    let t = t.trim().to_ascii_lowercase();
    let t = t.replace("joker", "any");
    let t = match t.strip_prefix("array[] of ") {
        Some(rest) => format!("array of [{rest}]"),
        None => t,
    };
    match t.as_str() {
        "string" => "text".into(),
        // The compiler names a record parameter `Table`, the runtime catalog `Record`.
        "table" => "record".into(),
        _ => t,
    }
}

/// Splits at top-level `,` (outside `[..]`).
fn split_top(s: &str) -> Vec<String> {
    let (mut depth, mut cur, mut out) = (0i32, String::new(), Vec::new());
    for c in s.chars() {
        match c {
            '[' => {
                depth += 1;
                cur.push(c)
            }
            ']' => {
                depth -= 1;
                cur.push(c)
            }
            ',' if depth == 0 => out.push(std::mem::take(&mut cur)),
            c => cur.push(c),
        }
    }
    out.push(cur);
    out.into_iter()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

/// The parameter shapes of a compiler `sig` (`(Text, [var Integer], Joker...)`).
pub fn compiler_shapes(sig: &str) -> Vec<Shape> {
    let inner = sig.trim().trim_start_matches('(').trim_end_matches(')');
    split_top(inner)
        .into_iter()
        .map(|p| {
            // `[..]` around the whole parameter is optional; `List of [T]` is a type.
            let optional = p.starts_with('[') && p.ends_with(']');
            let p = if optional { &p[1..p.len() - 1] } else { p.as_str() };
            let (by_var, p) = match p.strip_prefix("var ") {
                Some(r) => (true, r),
                None => (false, p),
            };
            let (variadic, p) = match p.strip_suffix("...") {
                Some(r) => (true, r),
                None => (false, p),
            };
            Shape {
                ty: norm_type(p),
                by_var,
                optional,
                variadic,
            }
        })
        .collect()
}

/// The parameter shapes of a runtime catalog signature.
pub fn runtime_shapes(sig: &al_builtins::signature::Signature) -> Vec<Shape> {
    sig.params
        .iter()
        .map(|p| Shape {
            ty: norm_type(&p.ty),
            by_var: p.by_var,
            optional: p.optional,
            variadic: p.variadic,
        })
        .collect()
}

/// How a compiler overload was matched to a runtime overload.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Match {
    /// Same parameter types and the same `var`, optional and repeat flags.
    Exact,
    /// Same parameter types and `var` flags; optional or repeat flags differ.
    Types,
    /// Same number of parameters (the two spell a type differently).
    Arity,
    /// The only overload of the method on both sides.
    Name,
}

/// Every compiler method overload (in catalog order) with the runtime overload id it matches, and
/// the runtime ids no compiler overload matched.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MethodMatch {
    pub matched: Vec<Option<(String, Match)>>,
    pub runtime_only: Vec<String>,
}

pub fn match_methods(lang: &LanguageCatalog, runtime: &al_builtins::catalog::Catalog) -> MethodMatch {
    use std::collections::{HashMap, HashSet};
    // Runtime overloads per (receiver, lower-case name, instance).
    let mut by_name: HashMap<MethodKey, Vec<(String, Vec<Shape>)>> = HashMap::new();
    for sig in &runtime.signatures {
        by_name
            .entry((sig.receiver.clone(), sig.name.to_ascii_lowercase(), sig.instance))
            .or_default()
            .push((runtime.id(sig), runtime_shapes(sig)));
    }
    let methods: Vec<&Entry> = lang.area("methods").collect();
    let mut count: HashMap<MethodKey, usize> = HashMap::new();
    for m in &methods {
        *count.entry(method_key(m)).or_default() += 1;
    }
    // A runtime overload is taken once per compiler owner (TextConst and Label share the Label ones).
    let mut used: HashSet<(String, String)> = HashSet::new();
    let mut matched = Vec::with_capacity(methods.len());
    // Exact matches first over the whole catalog, so a looser match never takes the overload an
    // exact one needs.
    let shapes: Vec<Vec<Shape>> = methods.iter().map(|m| compiler_shapes(&m.sig)).collect();
    let mut result: Vec<Option<(String, Match)>> = vec![None; methods.len()];
    let levels: [(Match, SameShape); 3] = [
        (Match::Exact, |a, b| a == b),
        (Match::Types, |a, b| {
            a.len() == b.len() && a.iter().zip(b).all(|(x, y)| x.ty == y.ty && x.by_var == y.by_var)
        }),
        (Match::Arity, |a, b| a.len() == b.len()),
    ];
    for (level, same) in levels {
        for (i, m) in methods.iter().enumerate() {
            if result[i].is_some() {
                continue;
            }
            let Some(cands) = by_name.get(&method_key(m)) else {
                continue;
            };
            let owner = &m.owner;
            if let Some((id, _)) = cands
                .iter()
                .find(|(id, s)| !used.contains(&(owner.clone(), id.clone())) && same(&shapes[i], s))
            {
                used.insert((owner.clone(), id.clone()));
                result[i] = Some((id.clone(), level));
            }
        }
    }
    for (i, m) in methods.iter().enumerate() {
        if result[i].is_some() {
            continue;
        }
        let key = method_key(m);
        if count.get(&key) != Some(&1) {
            continue;
        }
        if let Some(cands) = by_name.get(&key) {
            let free: Vec<_> = cands
                .iter()
                .filter(|(id, _)| !used.contains(&(m.owner.clone(), id.clone())))
                .collect();
            if cands.len() == 1 && free.len() == 1 {
                used.insert((m.owner.clone(), free[0].0.clone()));
                result[i] = Some((free[0].0.clone(), Match::Name));
            }
        }
    }
    matched.extend(result);
    let mut runtime_only: Vec<String> = runtime
        .signatures
        .iter()
        .map(|s| runtime.id(s))
        .filter(|id| !used.iter().any(|(_, u)| u == id))
        .collect();
    runtime_only.sort();
    MethodMatch { matched, runtime_only }
}

/// (runtime receiver, lower-case name, instance method).
type MethodKey = (String, String, bool);
/// Whether two parameter lists match at one level.
type SameShape = fn(&[Shape], &[Shape]) -> bool;

fn method_key(m: &Entry) -> MethodKey {
    (
        runtime_receiver(&m.owner).to_string(),
        m.name.to_ascii_lowercase(),
        !m.is_static,
    )
}

// ---------------------------------------------------------------------------------------------
// Behavior: the coverage map's groups (`<object kind>[/<section>]`) against the compiler's owners

/// The compiler trigger owners a trigger in coverage group `group` can belong to (the trigger's
/// name decides among them).
pub fn trigger_owners(group: &str) -> &'static [&'static str] {
    match group {
        "table" => &["Table"],
        "tableextension" => &["TableExtension"],
        "table/field" | "tableextension/field" => &["Field"],
        "tableextension/modify" => &["FieldExtension"],
        "page" => &["Page"],
        "pageextension" => &["PageExtension"],
        "page/field"
        | "page/usercontrol"
        | "page/part"
        | "pageextension/field"
        | "report/field"
        | "reportextension/field"
        | "xmlport/field" => &["Control"],
        "pageextension/modify" => &["ControlExtension", "ActionExtension"],
        "page/action"
        | "page/systemaction"
        | "pageextension/action"
        | "report/action"
        | "reportextension/action"
        | "xmlport/action" => &["Action"],
        "page/fileuploadaction" | "pageextension/fileuploadaction" => &["FileUploadAction"],
        "codeunit" => &["Codeunit"],
        "query" => &["Query"],
        "report" => &["Report"],
        "report/dataitem" | "reportextension/dataitem" => &["ReportDataItem"],
        "report/requestpage" | "xmlport/requestpage" => &["RequestPage"],
        "reportextension" => &["ReportExtension"],
        "reportextension/modify" => &["ReportExtensionDataSetModify", "ControlExtension", "ActionExtension"],
        "reportextension/requestpage" => &["RequestPageExtension"],
        "xmlport" => &["XmlPort"],
        "xmlport/tableelement" => &["XmlPortTableElement"],
        "xmlport/fieldelement" => &["XmlPortFieldElement"],
        "xmlport/textelement" => &["XmlPortTextElement"],
        "xmlport/fieldattribute" => &["XmlPortFieldAttribute"],
        "xmlport/textattribute" => &["XmlPortTextAttribute"],
        _ => &[],
    }
}

/// The catalog property owners (the probe contexts of `tools/language-catalog/probes.py`) a
/// property in coverage group `group` can belong to.
pub fn property_owners(group: &str) -> &'static [&'static str] {
    match group {
        "table" => &["Table"],
        "tableextension" => &["TableExtension"],
        "table/field" | "tableextension/field" => &["Field"],
        "tableextension/modify" => &["FieldModify"],
        "table/key" | "tableextension/key" => &["Key"],
        "table/fieldgroup" | "tableextension/fieldgroup" => &["FieldGroup"],
        "page" => &["Page"],
        "pageextension" => &["PageExtension"],
        "page/field" | "pageextension/field" | "report/field" | "reportextension/field" => &["PageField"],
        "page/group" | "pageextension/group" | "report/group" | "reportextension/group" => {
            &["PageGroup", "PageActionGroup"]
        }
        "page/repeater" | "pageextension/repeater" => &["PageRepeater"],
        "page/cuegroup" | "pageextension/cuegroup" => &["PageCueGroup"],
        "page/grid" | "pageextension/grid" => &["PageGrid"],
        "page/fixed" | "pageextension/fixed" => &["PageFixed"],
        "page/area" | "pageextension/area" | "report/area" => &["PageArea", "PageActionArea"],
        "page/part" | "pageextension/part" => &["PagePart"],
        "page/systempart" | "pageextension/systempart" => &["PageSystemPart"],
        "page/chartpart" | "pageextension/chartpart" => &["PageChartPart"],
        "page/label" | "pageextension/label" | "report/label" => &["PageLabel"],
        "page/usercontrol" | "pageextension/usercontrol" => &["PageUserControl"],
        "page/action" | "pageextension/action" | "report/action" | "reportextension/action" => &["PageAction"],
        "page/actionref" | "pageextension/actionref" => &["PageActionRef"],
        "page/separator" | "pageextension/separator" => &["PageActionSeparator"],
        "page/customaction" | "pageextension/customaction" => &["PageCustomAction"],
        "page/systemaction" | "pageextension/systemaction" => &["PageSystemAction"],
        "page/fileuploadaction" | "pageextension/fileuploadaction" => &["PageFileUploadAction"],
        "page/view" | "pageextension/view" => &["PageView"],
        "page/analysisview" | "pageextension/analysisview" => &["PageAnalysisView"],
        "pageextension/modify" | "reportextension/requestpage/modify" => &["PageControlModify", "PageActionModify"],
        "pagecustomization" => &["PageCustomizationObject"],
        "pagecustomization/modify" => &["AllPageCustomization"],
        "codeunit" => &["Codeunit"],
        "controladdin" => &["ControlAddInObject"],
        "entitlement" => &["Entitlement"],
        "enum" => &["EnumType"],
        "enumextension" => &["EnumExtension"],
        "enum/value" | "enumextension/value" => &["EnumValue"],
        "interface" => &["Interface"],
        "permissionset" => &["PermissionSet"],
        "permissionsetextension" => &["PermissionSetExtension"],
        "profile" | "profileextension" => &["Profile"],
        "query" => &["Query"],
        "query/column" => &["QueryColumn"],
        "query/dataitem" => &["QueryDataItem"],
        "query/filter" => &["QueryFilter"],
        "report" => &["Report"],
        "report/column" | "reportextension/column" => &["ReportColumn"],
        "report/dataitem" | "reportextension/dataitem" => &["ReportDataItem"],
        "report/layout" | "reportextension/layout" => &["ReportLayout"],
        "report/requestpage" | "xmlport/requestpage" => &["RequestPage"],
        "reportextension" => &["ReportExtension"],
        "reportextension/modify" => &["ReportExtensionModify"],
        "reportextension/requestpage" => &["RequestPageExtension"],
        "xmlport" => &["XmlPort"],
        "xmlport/tableelement" => &["XmlPortTableElement"],
        "xmlport/fieldelement" => &["XmlPortFieldElement"],
        "xmlport/textelement" => &["XmlPortTextElement"],
        "xmlport/fieldattribute" => &["XmlPortFieldAttribute"],
        "xmlport/textattribute" => &["XmlPortTextAttribute"],
        "dotnet" => &["DotNetAssembly"],
        "dotnet/assembly" => &["DotNetAssembly"],
        "dotnet/type" => &["DotNetTypeDeclaration"],
        _ => &[],
    }
}

/// The compiler owner of a trigger event (`OnAfterInsertEvent`) subscribed to in group `group`.
pub fn event_owner(group: &str) -> Option<&'static str> {
    match group {
        "table" => Some("Table"),
        "page" => Some("Page"),
        _ => None,
    }
}

/// The coverage map's syntax items a statement keyword of the catalog stands for. `None`: the
/// keyword has no item of its own (`else` belongs to `if` and `case`).
pub fn syntax_items(keyword: &str) -> Option<&'static [&'static str]> {
    Some(match keyword.to_ascii_lowercase().as_str() {
        "asserterror" => &["AssertErrorStmt"],
        "begin" => &["Block"],
        "break" => &["BreakStmt"],
        "case" => &["CaseStmt"],
        "continue" => &["ContinueStmt"],
        "exit" => &["ExitStmt"],
        "for" => &["ForStmt"],
        "foreach" => &["ForeachStmt"],
        "if" => &["IfStmt"],
        "repeat" => &["RepeatStmt"],
        "while" => &["WhileStmt"],
        "with" => &["WithStmt"],
        "not" => &["PrefixExpr not"],
        "this" => &["NameRef this"],
        "true" => &["Literal:true"],
        "false" => &["Literal:false"],
        _ => return None,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"{
"sources": [{"bc":27,"al_extension":"16.4"}, {"bc":28,"al_extension":"17.0"}, {"bc":29,"al_extension":"18.1"}],
"items": [
{"area":"methods","owner":"Record","name":"SetFilter","sig":"(Joker, Text, [Joker...])","params":"Field: Joker; String: Text; [Value: Joker...]","bc":[27,28,29]},
{"area":"methods","owner":"Dictionary","name":"Set","sig":"(TKey, TValue, var TValue)","params":"","returns":"Boolean","bc":[27,28,29]},
{"area":"methods","owner":"Dictionary","name":"Set","sig":"(TKey, TValue)","params":"","bc":[27,28,29]},
{"area":"methods","owner":"Text","name":"NoSuchMethod","sig":"()","params":"","static":true,"bc":[29]},
{"area":"methods","owner":"Dialog","name":"Message","sig":"(Text, [Joker...])","params":"","static":true,"bc":[27,28,29]},
{"area":"properties","owner":"Table","name":"DataPerCompany","type":"Boolean","in_extensions":true,"bc":[27,28,29]}
]}"#;

    #[test]
    fn the_catalog_parses_with_its_sources_and_majors() {
        let c = LanguageCatalog::parse(SAMPLE).unwrap();
        assert_eq!(c.majors(), "27-29");
        assert_eq!(c.area("methods").count(), 5);
        let p = c.area("properties").next().unwrap();
        assert!(p.in_extensions);
        assert_eq!(p.value_type, "Boolean");
        assert_eq!(majors(&[27, 29]), "27, 29");
    }

    #[test]
    fn compiler_signatures_split_into_shapes() {
        let s = compiler_shapes("(Joker, var List of [Text], [Integer], Joker...)");
        assert_eq!(s.len(), 4);
        assert_eq!(s[0].ty, "any");
        assert!(s[1].by_var && s[1].ty == "list of [text]" && !s[1].optional);
        assert!(s[2].optional && s[2].ty == "integer");
        assert!(s[3].variadic && !s[3].optional);
        assert_eq!(
            compiler_shapes("([Joker...])")[0],
            Shape {
                ty: "any".into(),
                by_var: false,
                optional: true,
                variadic: true
            }
        );
        assert!(compiler_shapes("()").is_empty());
        assert_eq!(compiler_shapes("(var array[] of Joker)")[0].ty, "array of [any]");
    }

    #[test]
    fn compiler_overloads_match_the_runtime_catalog_by_shape() {
        let c = LanguageCatalog::parse(SAMPLE).unwrap();
        let runtime = al_builtins::catalog::Catalog::load();
        let m = match_methods(&c, &runtime);
        assert_eq!(m.matched.len(), 5);
        // Record.SetFilter matches exactly.
        let (id, how) = m.matched[0].clone().unwrap();
        assert!(id.starts_with("Record.SetFilter#"), "{id}");
        assert_eq!(how, Match::Exact);
        // Two Dictionary.Set overloads each find their own.
        let a = m.matched[1].clone().unwrap().0;
        let b = m.matched[2].clone().unwrap().0;
        assert!(a.starts_with("Dictionary.Set#") && b.starts_with("Dictionary.Set#") && a != b);
        assert_eq!(runtime.by_id(&a).unwrap().params.len(), 3);
        assert!(m.matched[3].is_none(), "unknown to the runtime");
        assert!(m.matched[4].as_ref().unwrap().0.starts_with("Dialog.Message#"));
        assert!(!m.runtime_only.iter().any(|i| i == &a || i == &b));
        assert!(
            m.runtime_only.iter().any(|i| i.starts_with("Record.Insert#")),
            "not in the sample"
        );
    }

    #[test]
    fn a_textconst_overload_matches_the_label_overload_the_checker_resolves_to() {
        let c = LanguageCatalog::parse(
            r#"{"sources":[{"bc":27,"al_extension":"a"}],"items":[
{"area":"methods","owner":"Label","name":"ToUpper","sig":"()","returns":"Text","bc":[27]},
{"area":"methods","owner":"TextConst","name":"ToUpper","sig":"()","returns":"Text","bc":[27]}
]}"#,
        )
        .unwrap();
        let m = match_methods(&c, &al_builtins::catalog::Catalog::load());
        let a = m.matched[0].clone().unwrap().0;
        assert!(a.starts_with("Label.ToUpper#"), "{a}");
        assert_eq!(m.matched[1].clone().unwrap().0, a);
    }

    #[test]
    fn coverage_groups_map_to_compiler_owners() {
        assert_eq!(trigger_owners("table/field"), &["Field"]);
        assert_eq!(trigger_owners("tableextension/modify"), &["FieldExtension"]);
        assert!(trigger_owners("pageextension/modify").contains(&"ActionExtension"));
        assert_eq!(property_owners("tableextension"), &["TableExtension"]);
        assert_eq!(property_owners("tableextension/modify"), &["FieldModify"]);
        assert!(property_owners("page/group").contains(&"PageActionGroup"));
        assert_eq!(event_owner("table"), Some("Table"));
        assert_eq!(event_owner("codeunit"), None);
        assert!(trigger_owners("nonsense").is_empty());
    }

    #[test]
    fn statement_keywords_map_to_grammar_items() {
        assert_eq!(syntax_items("if"), Some(&["IfStmt"][..]));
        assert_eq!(syntax_items("asserterror"), Some(&["AssertErrorStmt"][..]));
        assert_eq!(syntax_items("this"), Some(&["NameRef this"][..]));
        assert_eq!(syntax_items("else"), None);
    }

    /// The committed catalog: parses, covers every area, and names only the majors it was built for.
    #[test]
    fn the_committed_catalog_is_well_formed() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let c = LanguageCatalog::load(&root).unwrap();
        let majors: Vec<u32> = c.sources.iter().map(|s| s.bc).collect();
        for area in [
            "datatypes",
            "methods",
            "triggers",
            "events",
            "properties",
            "syntax",
            "attributes",
        ] {
            assert!(c.area(area).count() > 0, "{area} is empty");
        }
        for e in &c.items {
            assert!(!e.bc.is_empty() && e.bc.iter().all(|b| majors.contains(b)), "{e:?}");
        }
        // The lists are facts only: no documentation text.
        assert!(
            !std::fs::read_to_string(root.join(PATH))
                .unwrap()
                .contains("\"description\"")
        );
    }

    /// The compiler spells a record parameter `Table`, the runtime catalog `Record`: the two are one
    /// type, so `Page.Run(Integer, [Table], [Joker])` matches its runtime overload exactly and not by
    /// arity to the `FullyQualifiedName: Text` one.
    #[test]
    fn a_table_parameter_matches_a_record_parameter() {
        let catalog = al_builtins::catalog::Catalog::load();
        let run = catalog
            .overloads("Page", "Run")
            .into_iter()
            .find(|s| s.to_line() == "Page.Run static (Number: Integer, ?Record: Record, ?Field: Any)")
            .unwrap();
        assert_eq!(compiler_shapes("(Integer, [Table], [Joker])"), runtime_shapes(run));
    }
}
